import{_ as t,o as n,c as o,ah as i}from"./chunks/framework.C-FRNfAJ.js";const h=JSON.parse('{"title":"Funding an event","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/activites/financement-evenements.md","filePath":"src/en/guide/activites/financement-evenements.md"}'),r={name:"en/guide/activites/financement-evenements.md"};function a(s,e,c,d,l,u){return n(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="funding-an-event" tabindex="-1">Funding an event <a class="header-anchor" href="#funding-an-event" aria-label="Permalink to &quot;Funding an event&quot;">​</a></h1><p>A funder can support a NextBoxx community event with a <strong>contribution</strong>, in money or in kind. The <strong>Events Officer</strong> records receipt of contributions and keeps the expenses.</p><h2 id="becoming-an-event-funder" tabindex="-1">Becoming an Event Funder <a class="header-anchor" href="#becoming-an-event-funder" aria-label="Permalink to &quot;Becoming an Event Funder&quot;">​</a></h2><p>The <strong>Event funder</strong> role stays open to <strong>individual accounts</strong> as well as organization accounts. Ask for it in <strong>Settings → Roles</strong>: the Events Officer examines it. It is also assigned to you automatically when the Officer records a contribution in your name.</p><h2 id="declaring-a-contribution" tabindex="-1">Declaring a contribution <a class="header-anchor" href="#declaring-a-contribution" aria-label="Permalink to &quot;Declaring a contribution&quot;">​</a></h2><p>In <strong>Activities → My funding</strong>, <strong>Declare a contribution</strong> asks for:</p><ul><li>the <strong>event</strong>: it must be published, not cancelled and not yet over;</li><li>the <strong>kind</strong>: financial, in kind or other;</li><li>a <strong>description</strong>;</li><li>the <strong>amount</strong> in FCFA, or, for an in-kind or other contribution, its <strong>valuation</strong> in FCFA.</li></ul><p>Your contribution stays <strong>Declared</strong> until NextBoxx <strong>records its receipt</strong>, or <strong>refuses</strong> it with a reason that you receive by e-mail. It is never counted automatically, and no invoice is issued.</p><p>When the contribution is received, NextBoxx sends you your <strong>funding agreement</strong> (<code>CONVE-NB-YYYY-XXX</code>) by e-mail. It is not signed electronically.</p><h2 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h2><p><strong>My funding</strong> lists your contributions, with their status (<strong>Declared</strong>, <strong>Received</strong>, <strong>Refused</strong>, <strong>Cancelled</strong>) and their agreement. For each event you fund, you see the <strong>total contributions received</strong>, the <strong>total expenses</strong> and the <strong>net balance</strong>. You see neither the detail of other funders, nor that of expenses.</p><p>If the event is <strong>cancelled</strong>, your declared contributions are cancelled. Contributions already received stay in the balance and you are notified; their return is settled outside Kura.</p><h2 id="follow-up-by-the-events-officer" tabindex="-1">Follow-up by the Events Officer <a class="header-anchor" href="#follow-up-by-the-events-officer" aria-label="Permalink to &quot;Follow-up by the Events Officer&quot;">​</a></h2><p>On an event&#39;s page, the <strong>Funding</strong> section shows contributions received, expenses and net balance, with the list of contributions.</p><ul><li><strong>Record receipt</strong> of a declared contribution, with the date: it enters the balance and its funding agreement is issued and sent.</li><li><strong>Refuse</strong> a contribution, with a reason given to the funder.</li><li><strong>Record a contribution</strong> for an existing account, for example after the fact, even after the event ends. Enter the account&#39;s e-mail address; if you fill in &quot;Already received on&quot;, receipt is recorded at once. The account receives the Event funder role.</li><li><strong>Add an expense</strong>: label, amount, date and optional receipt (PDF, JPG or PNG, 5 MB at most). You can correct or delete it; each entry, correction or deletion is traced in the log.</li><li><strong>Note the return</strong> of a contribution received after the event is cancelled, with its date: the refund is settled outside Kura and the contribution stays in the balance.</li></ul><p>The <strong>net balance</strong> is the total contributions received minus expenses.</p>',16)])])}const f=t(r,[["render",a]]);export{h as __pageData,f as default};
